//! M5 — embedded TrueType text rendering (ISO 32000-1 §9).
//!
//! Covers the M5 scope: `/Subtype /TrueType` + `/FontFile2`,
//! `WinAnsiEncoding` (named or via an encoding dictionary with
//! `BaseEncoding`/`Differences`), `BT`/`ET`, `Tf`, `Tc`/`Tw`/`Tz`/
//! `Ts`/`TL`/`Tr`, `Tm`/`Td`/`TD`/`T*`, `Tj`/`TJ`/`'`/`"`,
//! rendering modes 0–3, Form-internal text, and the refusals for
//! unsupported fonts, encodings, and modes.
//!
//! The fixture font is `KasaneTest.ttf` — generated by
//! `tests/fixtures/make_font.py` (fontTools, Apache-2.0) with a
//! permissive design: all glyphs are boxes so pixel checks are
//! trivially verifiable.

use kasane_pdf::{render_page, Document, Error, Limits, RenderOptions};

fn fixture(name: &str) -> Vec<u8> {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {path}: {e}"))
}

fn render(name: &str) -> Result<kasane_pdf::RenderedPage, Error> {
    let pdf = fixture(name);
    let doc = Document::from_bytes(&pdf)?;
    render_page(&doc, &doc.pages()[0], &RenderOptions::default())
}

fn render_lim(name: &str, limits: Limits) -> Result<kasane_pdf::RenderedPage, Error> {
    let pdf = fixture(name);
    let doc = Document::from_bytes(&pdf)?;
    render_page(
        &doc,
        &doc.pages()[0],
        &RenderOptions {
            limits,
            ..RenderOptions::default()
        },
    )
}

fn ink_bbox(page: &kasane_pdf::RenderedPage) -> Option<(u32, u32, u32, u32)> {
    let (mut minx, mut miny, mut maxx, mut maxy) = (u32::MAX, u32::MAX, 0, 0);
    let mut any = false;
    for y in 0..page.pixmap.height() {
        for x in 0..page.pixmap.width() {
            let p = page.pixmap.pixel(x, y).unwrap();
            if (p.red(), p.green(), p.blue()) != (255, 255, 255) {
                minx = minx.min(x);
                miny = miny.min(y);
                maxx = maxx.max(x);
                maxy = maxy.max(y);
                any = true;
            }
        }
    }
    any.then_some((minx, miny, maxx, maxy))
}

// --------------------------------------------------------------------
// Basic rendering
// --------------------------------------------------------------------

#[test]
fn text_basic_paints() {
    // "ABC" at 24pt, baseline at user y=60 — glyphs occupy roughly
    // (20..63, 61..76) in page coords → pixmap y 24..39.
    let r = render("text_basic.pdf").unwrap();
    let (minx, miny, maxx, maxy) = ink_bbox(&r).unwrap();
    assert_eq!(minx, 20);
    assert_eq!(miny, 23);
    assert_eq!(maxx, 63);
    assert_eq!(maxy, 39);
}

#[test]
fn text_tj_adjusts_spacing() {
    // TJ [-120, 60] adjustments shift B left and C right vs. plain Tj.
    let r = render("text_tj.pdf").unwrap();
    let (minx, _miny, maxx, _maxy) = ink_bbox(&r).unwrap();
    // Compared to text_basic's [20..63], TJ pushes the last glyph out.
    assert!(maxx > 63 || minx < 20, "TJ didn't shift");
}

#[test]
fn quote_operators_advance_lines() {
    // Three lines of text at different baselines.
    let r = render("text_quote_ops.pdf").unwrap();
    let (_minx, miny, _maxx, maxy) = ink_bbox(&r).unwrap();
    // Three lines → text spans more vertically than one line.
    assert!(maxy - miny > 30, "only one line painted? y {miny}..{maxy}");
}

#[test]
fn text_tc_widens() {
    // Tc=2 should push glyphs further apart than plain Tj.
    let r = render("text_tc_tw_tz_ts.pdf").unwrap();
    // Just verify it renders; the width check is covered by the
    // Poppler comparison below.
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn render_modes_paint() {
    // Modes 0,1,2 produce ink; 3 is invisible.
    let r = render("text_render_modes.pdf").unwrap();
    // Page has text at y=80,60,40 (modes 0,1,2) and y=20 (mode 3).
    // Mode 3 must not paint — the lower-left area stays white.
    let (_minx, _miny, _maxx, maxy) = ink_bbox(&r).unwrap();
    // y=20's invisible text contributes nothing; ink stays in upper half.
    assert!(maxy < 80);
}

#[test]
fn mode3_still_advances_position() {
    // A glyph after an invisible one must be placed correctly — the
    // invisible one still consumes its advance.
    // Page: (A) invisibly, then (B) visibly — B starts after A's slot.
    let pdf = {
        let ttf = std::fs::read("tests/fixtures/KasaneTest.ttf").unwrap();
        let mut out = Vec::new();
        out.extend_from_slice(b"%PDF-1.4\n");
        let mut offs = Vec::new();
        let stream = b"BT /F1 20 Tf 10 60 Td 3 Tr (A) Tj 0 Tr (B) Tj ET";
        let bodies = [
            (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
            (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec()),
            (
                3,
                b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 200 100] \
                   /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>"
                    .to_vec(),
            ),
            (
                4,
                [
                    format!("<< /Length {} >>\nstream\n", stream.len()).into_bytes(),
                    stream.to_vec(),
                    b"\nendstream".to_vec(),
                ]
                .concat(),
            ),
            (
                5,
                b"<< /Type /Font /Subtype /TrueType /BaseFont /KasaneTest-Regular \
                   /Encoding /WinAnsiEncoding /FirstChar 65 /LastChar 66 \
                   /Widths [600 600] /FontDescriptor 6 0 R >>"
                    .to_vec(),
            ),
            (
                6,
                b"<< /Type /FontDescriptor /FontName /KasaneTest-Regular \
                   /Flags 32 /FontBBox [0 -200 600 800] /ItalicAngle 0 \
                   /Ascent 800 /Descent -200 /CapHeight 700 /StemV 80 \
                   /FontFile2 7 0 R >>"
                    .to_vec(),
            ),
            (
                7,
                [
                    format!(
                        "<< /Length {} /Filter /FlateDecode /Length1 {} >>\nstream\n",
                        flate(&ttf).len(),
                        ttf.len()
                    )
                    .into_bytes(),
                    flate(&ttf),
                    b"\nendstream".to_vec(),
                ]
                .concat(),
            ),
        ];
        for (n, b) in &bodies {
            offs.push((*n, out.len()));
            out.extend_from_slice(format!("{n} 0 obj\n").as_bytes());
            out.extend_from_slice(b);
            out.extend_from_slice(b"\nendobj\n");
        }
        let xref = out.len();
        out.extend_from_slice(b"xref\n0 8\n");
        out.extend_from_slice(b"0000000000 65535 f \n");
        for (_n, off) in &offs {
            out.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
        }
        out.extend_from_slice(b"trailer\n<< /Size 8 /Root 1 0 R >>\n");
        out.extend_from_slice(format!("startxref\n{xref}\n%%EOF\n").as_bytes());
        out
    };
    let doc = Document::from_bytes(&pdf).unwrap();
    let r = render_page(&doc, &doc.pages()[0], &RenderOptions::default()).unwrap();
    let (minx, _miny, _maxx, _maxy) = ink_bbox(&r).unwrap();
    // A is invisible; B paints at x = 10 + 600/1000*20 = 22.
    assert_eq!(minx, 22);
}

fn flate(data: &[u8]) -> Vec<u8> {
    use flate2::write::ZlibEncoder;
    use flate2::Compression;
    use std::io::Write;
    let mut e = ZlibEncoder::new(Vec::new(), Compression::fast());
    e.write_all(data).unwrap();
    e.finish().unwrap()
}

