#[test]
fn composite_glyph_paints() {
    // 0xC4 = Ä — composite of A + dieresis dots.
    let r = render("text_composite_glyph.pdf").unwrap();
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn differences_remap_code() {
    // Differences [65 /B 66 /A]: code 65 → glyph B, code 66 → glyph A.
    // Rendered output is "BA" — B then A — so the *first* glyph drawn
    // (leftmost) is B. Both glyphs are identical boxes in our font, so
    // instead verify via Poppler that the *shapes* differ. Here we
    // just verify the pipeline ran without error.
    let r = render("text_differences_encoding.pdf").unwrap();
    assert!(ink_bbox(&r).is_some());
}

#[test]
fn notdef_for_unencoded_code() {
    // Char 0x01 has no WinAnsi entry → .notdef (a box in our font).
    let r = render("text_notdef.pdf").unwrap();
    let (minx, _miny, _maxx, _maxy) = ink_bbox(&r).unwrap();
    // A at x=20, .notdef after it, Z last — total advance = 3×600×24/1000 = 43.2
    assert!(minx >= 20);
}

