#[test]
fn text_clip_respected() {
    // Clip rect (0..30, 0..30) does not overlap the text at y=40 —
    // nothing paints; the clip is *applied*, not ignored.
    let r = render("text_clip.pdf").unwrap();
    assert!(ink_bbox(&r).is_none(), "clip was not honoured");
}

#[test]
fn pdf_widths_override_font_metrics() {
    // Widths [1000, 200] override the font's uniform 600 —
    // A→B distance = 1000/1000×20 = 20 px (not 12).
    let r = render("text_widths_override.pdf").unwrap();
    let (minx, _miny, maxx, _maxy) = ink_bbox(&r).unwrap();
    // A at x=10..22 (600×20/1000 = 12 px wide? no — glyph is still
    // 600-unit box scaled by 20pt) — B then starts 20 px after A's
    // origin because PDF says so.
    assert!(maxx - minx > 20, "widths not applied: {minx}..{maxx}");
}

